use rivet::{chat::{ChatOptions,Controls,Review,Reviewer},budget::BudgetLimits,config::{Project,ProviderConfig},domain::Mode,model_pool::*,scheduler};
use serde_json::{Value,json};use std::{path::Path,future::Future,pin::Pin,time::Duration};use tokio::{net::TcpListener,io::{AsyncReadExt,AsyncWriteExt}};use tokio_util::sync::CancellationToken;
struct Approved;impl Reviewer for Approved{fn approve(&mut self,_:Review)->Pin<Box<dyn Future<Output=rivet::error::Result<bool>>+Send+'_>>{Box::pin(async{Ok(true)})}}
async fn read(stream:&mut tokio::net::TcpStream)->Value{let mut bytes=vec![];let mut part=[0;4096];loop{let n=stream.read(&mut part).await.unwrap();assert!(n>0);bytes.extend_from_slice(&part[..n]);assert!(bytes.len()<1024*1024);if let Some(end)=bytes.windows(4).position(|b|b==b"\r\n\r\n"){let headers=String::from_utf8_lossy(&bytes[..end]);let size=headers.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|s|s.parse::<usize>().ok())).unwrap();if bytes.len()>=end+4+size{return serde_json::from_slice(&bytes[end+4..]).unwrap();}}}}
async fn reply(stream:&mut tokio::net::TcpStream){let body=format!("data: {}\n\ndata: {}\n\ndata: [DONE]\n\n",json!({"choices":[{"index":0,"delta":{"content":"synthetic role completed exact scope"},"finish_reason":"stop"}]}),json!({"choices":[],"usage":{"prompt_tokens":10,"completion_tokens":10}}));stream.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).as_bytes()).await.unwrap();stream.write_all(body.as_bytes()).await.unwrap();}
fn policy(endpoint:String,behavior:Behavior)->Policy{let slots=if behavior==Behavior::Concurrent{2}else{1};let mut p=Profile{id:"a".into(),provider:ProviderConfig{profile:"llama.cpp-compatible".into(),endpoint,model:"synthetic-a".into(),context_tokens:Some(65536)},instance:"resident-a".into(),resident:true,remote:false,weights_ram:128*1024*1024,weights_vram:0,kv_ram_per_token:16,kv_vram_per_token:0,slots,loading_ram:64*1024*1024,loading_vram:0,qualification:None};if slots==2{p.qualification=Some(Qualification{profile_digest:p.digest().unwrap(),evidence_sha256:"a".repeat(64),owner_statement:"Synthetic endpoint test: two simultaneous requests accepted; not a real model capacity claim".into()});}let mut profiles=vec![p.clone()];let mut assignments=vec!["a".into(),"a".into()];let phases=if behavior==Behavior::Relay{p.id="b".into();p.instance="resident-b".into();p.provider.model="synthetic-b".into();profiles.push(p);assignments[1]="b".into();vec![Phase{tasks:vec![0],profile:"a".into(),goal:PhaseGoal::WaitingOrSucceeded},Phase{tasks:vec![1],profile:"b".into(),goal:PhaseGoal::Succeeded},Phase{tasks:vec![0],profile:"a".into(),goal:PhaseGoal::Succeeded}]}else{vec![]};Policy{adaptive:None,schema_version:1,behavior,limits:Limits{ram:2*1024*1024*1024,vram:0,os_ram:256*1024*1024,tools_ram:1024*1024*1024,browser_ram:0,loading_overlap_ram:32*1024*1024,loading_overlap_vram:0},profiles,assignments,phases}}
fn options()->ChatOptions{ChatOptions{session:None,task:"synthetic model policy".into(),steps:20,deadline_seconds:60,budget:BudgetLimits{tokens:200_000,requests:20,cost_micros:0},request_cost_micros:0,credential:None,mcp:vec![],skills:vec![]}}
#[tokio::test]
async fn shared_concurrent_and_serial_relay_use_real_synthetic_streams_and_one_budget(){
    for behavior in [Behavior::Shared,Behavior::Concurrent,Behavior::Relay]{tokio::time::timeout(Duration::from_secs(20),async{
        let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let parallel=behavior==Behavior::Concurrent;let relay=behavior==Behavior::Relay;
        let server=tokio::spawn(async move{let(mut first,_)=listener.accept().await.unwrap();let first_request=read(&mut first).await;
            if parallel{let(mut second,_)=tokio::time::timeout(Duration::from_secs(2),listener.accept()).await.unwrap().unwrap();let second_request=read(&mut second).await;assert_ne!(first_request["messages"][0],second_request["messages"][0]);reply(&mut second).await;reply(&mut first).await;}
            else{assert!(tokio::time::timeout(Duration::from_millis(30),listener.accept()).await.is_err());reply(&mut first).await;let(mut second,_)=listener.accept().await.unwrap();let request=read(&mut second).await;if relay{assert_eq!(request["model"],"synthetic-b");}reply(&mut second).await;}
            let(mut last,_)=listener.accept().await.unwrap();let request=read(&mut last).await;assert_eq!(request["model"],"synthetic-a");assert!(request.to_string().contains("checks"));reply(&mut last).await;
        });
        let policy=policy(format!("http://{address}/v1/chat/completions"),behavior.clone());let config=policy.profiles[0].provider.clone();let plan=scheduler::template(Mode::Pair,"bounded synthetic hierarchy",vec![]).unwrap();let result=rivet::hierarchy::run_configured(&project,Path::new("state"),config,options(),Some(plan),None,Some(policy),&mut Approved,CancellationToken::new(),Controls::default()).await.unwrap();server.await.unwrap();assert_eq!(result.steps,3);let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let(text,requests,unknown):(String,i64,i64)=db.query_row("SELECT (SELECT document FROM model_pools),(SELECT requests FROM run_budgets),(SELECT count(*) FROM inference_reservations WHERE state!='settled')",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();let state:State=serde_json::from_str(&text).unwrap();assert!(state.reservations.is_empty());assert_eq!(requests,3);assert_eq!(unknown,0);if behavior==Behavior::Relay{assert_eq!(state.phase,2);assert_eq!(state.handoffs.len(),3);}
    }).await.unwrap();}
}
#[tokio::test]
async fn provider_eof_holds_resources_and_explicit_owner_observation_never_refunds_budget(){
    let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let server=tokio::spawn(async move{let(mut stream,_)=listener.accept().await.unwrap();read(&mut stream).await;stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: 1\r\nConnection: close\r\n\r\nx").await.unwrap();});let policy=policy(format!("http://{address}/v1/chat/completions"),Behavior::Shared);let config=policy.profiles[0].provider.clone();assert!(rivet::hierarchy::run_configured(&project,Path::new("state"),config,options(),Some(scheduler::template(Mode::Pair,"unknown request",vec![]).unwrap()),None,Some(policy),&mut Approved,CancellationToken::new(),Controls::default()).await.is_err());server.await.unwrap();let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let (run,text,budget):(String,String,i64)=db.query_row("SELECT (SELECT id FROM runs),(SELECT document FROM model_pools),(SELECT token_reserved FROM run_budgets)",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();let run=rivet::domain::RunId(uuid::Uuid::parse_str(&run).unwrap());let state:State=serde_json::from_str(&text).unwrap();assert_eq!(state.reservations.len(),1);assert!(state.reservations[0].unknown);assert!(budget>0);drop(db);
    let request=&state.reservations[0];let observation=OwnerObservation{request:Some(request.request),activation_digest:None,profile_digest:state.policy.profile(&request.profile).unwrap().digest().unwrap(),observed_complete:true,old_unloaded:false,new_resident:false,evidence_sha256:"c".repeat(64),owner_statement:"Synthetic fixture connection is closed; owner-observed completion, no billing refund".into()};assert!(rivet::model_pool::observe(&project,Path::new("state"),run,observation.clone(),Some("wrong")).await.is_err());let review=rivet::model_pool::observe(&project,Path::new("state"),run,observation.clone(),None).await.unwrap();rivet::model_pool::observe(&project,Path::new("state"),run,observation,review["review_digest"].as_str()).await.unwrap();let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let after:i64=db.query_row("SELECT token_reserved FROM run_budgets",[],|r|r.get(0)).unwrap();assert_eq!(after,budget);let text:String=db.query_row("SELECT document FROM model_pools",[],|r|r.get(0)).unwrap();assert!(serde_json::from_str::<State>(&text).unwrap().reservations.is_empty());
}

#[tokio::test]
async fn exhausted_parent_budget_rolls_back_pool_reservation_before_another_send(){
    let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let server=tokio::spawn(async move{let(mut stream,_)=listener.accept().await.unwrap();read(&mut stream).await;reply(&mut stream).await;assert!(tokio::time::timeout(Duration::from_millis(100),listener.accept()).await.is_err());});let policy=policy(format!("http://{address}/v1/chat/completions"),Behavior::Shared);let config=policy.profiles[0].provider.clone();let mut options=options();options.budget.requests=1;assert!(rivet::hierarchy::run_configured(&project,Path::new("state"),config,options,Some(scheduler::template(Mode::Pair,"one request ceiling",vec![]).unwrap()),None,Some(policy),&mut Approved,CancellationToken::new(),Controls::default()).await.is_err());server.await.unwrap();let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let(text,requests,reserved):(String,i64,i64)=db.query_row("SELECT (SELECT document FROM model_pools),(SELECT requests FROM run_budgets),(SELECT token_reserved FROM run_budgets)",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();assert_eq!((requests,reserved),(1,0));assert!(serde_json::from_str::<State>(&text).unwrap().reservations.is_empty());
}

#[tokio::test]
async fn mesh_and_adaptive_preserve_real_contexts_budget_and_role_history(){
    for adaptive in [false,true]{tokio::time::timeout(Duration::from_secs(20),async{
        let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let expected=if adaptive{3}else{4};let server=tokio::spawn(async move{let mut systems=vec![];for _ in 0..expected{let(mut stream,_)=listener.accept().await.unwrap();let value=read(&mut stream).await;systems.push(value["messages"][0]["content"].as_str().unwrap().to_owned());reply(&mut stream).await;}systems});let mut policy=policy(format!("http://{address}/v1/chat/completions"),Behavior::Shared);
        let plan=if adaptive{policy.adaptive=Some(rivet::adaptive::Policy{initial:Mode::Pair,allowed:vec![Mode::Pair,Mode::Solo],agent_ceiling:2,coordination:Some(false),review:Some(false),director:Some(false),tokens_per_actor:1,steps_per_actor:1,cost_per_actor:0,max_transitions:1,role_profiles:vec![],mesh_peers:2});scheduler::template(Mode::Pair,"adaptive scope unchanged",vec![]).unwrap()}else{scheduler::mesh_template("local peer scope",vec![],2).unwrap()};let config=policy.profiles[0].provider.clone();let result=rivet::hierarchy::run_configured(&project,Path::new("state"),config,options(),Some(plan),None,Some(policy),&mut Approved,CancellationToken::new(),Controls::default()).await.unwrap();let systems=server.await.unwrap();let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let (graph,specs,history,requests):(String,i64,i64,i64)=db.query_row("SELECT (SELECT document FROM coordination),(SELECT count(*) FROM run_specs),(SELECT count(*) FROM mode_history),(SELECT requests FROM run_budgets)",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).unwrap();let graph:rivet::scheduler::Graph=serde_json::from_str(&graph).unwrap();assert!(graph.done());assert_eq!(requests,expected);if adaptive{assert!(systems[0].contains("role Lead"));assert!(systems[1..].iter().all(|s|s.contains("role Independent")));assert_eq!(graph.plan.mode,Mode::Solo);assert_eq!(graph.plan.agents.len(),1);assert_eq!((specs,history),(2,1));drop(db);let preview=rivet::model_pool::restrict_modes(&project,Path::new("state"),result.run,vec![],None).await.unwrap();rivet::model_pool::restrict_modes(&project,Path::new("state"),result.run,vec![],preview["review_digest"].as_str()).await.unwrap();assert!(rivet::model_pool::restrict_modes(&project,Path::new("state"),result.run,vec![Mode::Solo],None).await.is_err());}else{assert!(systems.iter().all(|s|s.contains("role Independent")));assert_eq!(graph.plan.mode,Mode::Mesh);assert_eq!(graph.plan.agents.len(),2);assert!(graph.nodes.iter().filter(|n|n.task.kind==rivet::scheduler::Kind::Coding).all(|n|n.owner_assigned));}
    }).await.unwrap();}
}

#[tokio::test]
async fn mesh_conflict_pauses_for_main_chat_and_explicit_resume_never_replays_the_write(){
    let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let server=tokio::spawn(async move{let(mut stream,_)=listener.accept().await.unwrap();read(&mut stream).await;reply(&mut stream).await;for _ in 0..2{let(mut stream,_)=listener.accept().await.unwrap();read(&mut stream).await;let body=format!("data: {}\n\ndata: {}\n\ndata: [DONE]\n\n",json!({"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":uuid::Uuid::new_v4().to_string(),"type":"function","function":{"name":"rivet_files_v1","arguments":json!({"operation":"write","path":"shared.txt","expected":null,"text":"winner\n"}).to_string()}}]},"finish_reason":"tool_calls"}]}),json!({"choices":[],"usage":{"prompt_tokens":10,"completion_tokens":10}}));stream.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).as_bytes()).await.unwrap();stream.write_all(body.as_bytes()).await.unwrap();}});let config=ProviderConfig{profile:"llama.cpp-compatible".into(),endpoint:format!("http://{address}/v1/chat/completions"),model:"synthetic".into(),context_tokens:Some(65536)};assert!(rivet::hierarchy::run(&project,Path::new("state"),config,options(),scheduler::mesh_template("one reviewed shared path",vec!["shared.txt".into()],2).unwrap(),&mut Approved,CancellationToken::new()).await.is_err());server.await.unwrap();assert_eq!(std::fs::read_to_string(temp.path().join("shared.txt")).unwrap(),"winner\n");let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let(run,text,status):(String,String,String)=db.query_row("SELECT (SELECT id FROM runs),(SELECT document FROM coordination),(SELECT status FROM run_lifecycle)",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();assert_eq!(status,"paused");let graph:rivet::scheduler::Graph=serde_json::from_str(&text).unwrap();assert_eq!(graph.nodes.iter().filter(|n|n.state==rivet::scheduler::Status::WaitingInput).count(),1);assert!(!graph.done());drop(db);let run=rivet::domain::RunId(uuid::Uuid::parse_str(&run).unwrap());let before=rivet::lifecycle::inspect(&project,Path::new("state"),run).unwrap();let ledger=rivet::ledger::Ledger::open(&project,Path::new("state")).unwrap();let graph=ledger.graph(run).await.unwrap();assert!(ledger.coordinate(graph.revision,rivet::coordination::Command::ResumeConflicts{run}).await.is_err());ledger.life(before.revision,rivet::lifecycle::Command::Resume{run,wall:std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs(),approved:before.digest().unwrap(),detached:false}).await.unwrap();ledger.coordinate(graph.revision,rivet::coordination::Command::ResumeConflicts{run}).await.unwrap();let graph=ledger.graph(run).await.unwrap();assert!(!graph.nodes.iter().any(|n|n.state==rivet::scheduler::Status::WaitingInput));ledger.shutdown().unwrap();assert_eq!(std::fs::read_to_string(temp.path().join("shared.txt")).unwrap(),"winner\n");
}
